CREATE TABLE task(task_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,source_type VARCHAR(50) NOT NULL DEFAULT 'MANUAL',source_id BIGINT NULL,task_type VARCHAR(50) NOT NULL,title VARCHAR(200) NOT NULL,related_cattle_id BIGINT NULL,related_herd_id BIGINT NULL,related_barn_id BIGINT NULL,plan_date DATE NOT NULL,due_date DATE NOT NULL,assignee_id BIGINT NULL,priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL',status VARCHAR(20) NOT NULL DEFAULT 'PENDING',result VARCHAR(1000) NULL,completed_by BIGINT NULL,completed_at DATETIME NULL,cancel_reason VARCHAR(255) NULL,cancelled_by BIGINT NULL,cancelled_at DATETIME NULL,created_by BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_task_assignee_status_due(farm_id,assignee_id,status,due_date),INDEX idx_task_status_due(farm_id,status,due_date),INDEX idx_task_source(source_type,source_id),CONSTRAINT uk_task_source_type UNIQUE(farm_id,source_type,source_id,task_type));
CREATE TABLE task_target(target_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,task_id BIGINT NOT NULL,target_type VARCHAR(20) NOT NULL,target_object_id BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_task_target UNIQUE(task_id,target_type,target_object_id),INDEX idx_task_target_object(farm_id,target_type,target_object_id));
